const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const utahGeom = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'Utah'))
    .geometry();

  const targetStartDate = '2020-08-01';
  const targetEndDate = '2020-08-31';

  // Long-term is all available Augusts before 2020. SMAP started in 2015.
  const longTermStartYear = 2015;
  const longTermEndYear = 2019;

  // 2. Data Acquisition
  const smapCollection = ee.ImageCollection('NASA_USDA/HSL/SMAP10KM_soil_moisture')
    .select('ssm'); // Surface Soil Moisture

  const targetCollection = smapCollection.filterDate(targetStartDate, targetEndDate);
  const longTermCollection = smapCollection
    .filter(ee.Filter.calendarRange(longTermStartYear, longTermEndYear, 'year'))
    .filter(ee.Filter.calendarRange(8, 8, 'month'));

  // Data Availability Check
  const targetSize = targetCollection.size().getInfo();
  const longTermSize = longTermCollection.size().getInfo();

  if (targetSize === 0 || longTermSize === 0) {
    console.log(`Image collection size check failed.`);
    console.log(`August 2020 images found: ${targetSize}`);
    console.log(`Long-term (2015-2019) August images found: ${longTermSize}`);
    console.log('A: Yes');
    return;
  }
  console.log(`Images found for Aug 2020: ${targetSize}`);
  console.log(`Images found for Aug 2015-2019: ${longTermSize}`);

  // 3. Processing
  const targetMeanImage = targetCollection.mean().clip(utahGeom);
  const longTermMeanImage = longTermCollection.mean().clip(utahGeom);

  const scale = 10000; // SMAP native resolution is ~10km

  // 4. Calculation & Pixel Count Validation
  const reduceArgs = {
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: utahGeom,
    scale: scale,
    maxPixels: 1e9
  };

  const targetStats = targetMeanImage.reduceRegion(reduceArgs);
  const longTermStats = longTermMeanImage.reduceRegion(reduceArgs);

  const targetMean = targetStats.get('ssm_mean').getInfo();
  const targetCount = targetStats.get('ssm_count').getInfo();
  const longTermMean = longTermStats.get('ssm_mean').getInfo();
  const longTermCount = longTermStats.get('ssm_count').getInfo();

  if (targetCount === 0 || longTermCount === 0) {
    console.log(`No valid pixels found for one or both periods within the geometry.`);
    console.log(`Valid pixels in Aug 2020: ${targetCount}`);
    console.log(`Valid pixels in long-term Aug: ${longTermCount}`);
    console.log('C2');
    return;
  }

  if (targetMean === null || longTermMean === null) {
      console.log('Calculation resulted in null, indicating a potential issue.');
      console.log(`August 2020 Mean: ${targetMean}`);
      console.log(`Long-term Mean: ${longTermMean}`);
      console.log('C3');
      return;
  }

  // 5. Validation & Final Answer
  console.log(`Utah Surface Soil Moisture (Aug 2020): ${targetMean.toFixed(2)} mm`);
  console.log(`Utah Pixel Count (Aug 2020): ${targetCount}`);
  console.log(`Utah Long-Term Avg. Soil Moisture (Aug 2015-2019): ${longTermMean.toFixed(2)} mm`);
  console.log(`Utah Long-Term Pixel Count: ${longTermCount}`);

  if (targetMean < longTermMean) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during Earth Engine initialization or analysis.');
    console.error(e);
    console.log('D');
  }
}

initEE();
